# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import round_spans


class RoundingTests(unittest.TestCase):
    def test_label_after_snapping(self):
        spans = [Span(7 * 60 + 58, 17 * 60 + 12)]
        self.assertEqual(
            round_spans(spans, 15),
            ["08:00-17:15 (9h 15m)"]
        )

    def test_exact_times_unchanged(self):
        spans = [Span(540, 1035)]
        self.assertEqual(
            round_spans(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_nearest_step_wins(self):
        spans = [Span(547, 607)]
        self.assertEqual(
            round_spans(spans, 15),
            ["09:00-10:00 (1h 0m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)
